/**
 * T13 tests-first: canonical byte signing matches the Python golden fixture.
 *
 * The golden fixture is generated by ee/tests/test_m2_t13_web.py
 * (test_guard_golden_fixture_written) and lives at
 * ee/web/tests/fixtures/golden_canonical.json.
 *
 * The TS signing module (ee/web/src/signing.ts) must produce identical bytes
 * for the same tag and payload.  This proves the cross-language canonical form
 * is byte-for-byte consistent: ``tag || 0x00 || canonical JSON(payload)``.
 *
 * RED: these tests fail because ee/web/src/signing.ts does not exist yet.
 *
 * D5.6 field set (agg/remote-approval/v1):
 *   request_id, command, fingerprint, reviewer_id, decision, approved_at,
 *   org_id, project_id, device_id, registry_version, policy_sequence,
 *   user_id, key_id, nonce, not_after
 */
import { describe, it, expect } from "vitest";
import { readFileSync } from "node:fs";
import { resolve } from "node:path";

// This import will fail until the signing module is created (RED).
// @ts-expect-error Module does not exist yet (T13 RED)
import { canonicalBytes, canonicalJson, REMOTE_APPROVAL_TAG } from "../src/signing";

const FIXTURE_PATH = resolve(__dirname, "fixtures", "golden_canonical.json");

interface GoldenCase {
  name: string;
  tag: string;
  payload: Record<string, unknown>;
  canonical_json_hex: string;
  canonical_bytes_hex: string;
  canonical_bytes_sha256: string;
}

interface GoldenFixture {
  tag: string;
  payload: Record<string, unknown>;
  canonical_json_hex: string;
  canonical_bytes_hex: string;
  canonical_bytes_sha256: string;
  cases?: GoldenCase[];
}

function loadGolden(): GoldenFixture {
  const raw = readFileSync(FIXTURE_PATH, "utf-8");
  return JSON.parse(raw) as GoldenFixture;
}

describe("canonicalBytes (cross-language golden fixture)", () => {
  it("produces the same canonical JSON as Python for the golden payload", () => {
    const golden = loadGolden();
    const result = canonicalJson(golden.payload);
    const resultHex = Buffer.from(result).toString("hex");
    expect(resultHex).toBe(golden.canonical_json_hex);
  });

  it("produces the same canonical bytes as Python for the golden payload", () => {
    const golden = loadGolden();
    const result = canonicalBytes(golden.tag, golden.payload);
    const resultHex = Buffer.from(result).toString("hex");
    expect(resultHex).toBe(golden.canonical_bytes_hex);
  });

  it("uses the correct tag for remote approvals", () => {
    expect(REMOTE_APPROVAL_TAG).toBe("agg/remote-approval/v1");
  });

  it("separates tag and payload with a null byte", () => {
    const golden = loadGolden();
    const result = canonicalBytes(golden.tag, golden.payload);
    const tagBytes = new TextEncoder().encode(golden.tag);
    // Byte after the tag must be 0x00
    expect(result[tagBytes.length]).toBe(0x00);
  });

  it("uses sort_keys and compact separators in canonical JSON", () => {
    // Verify that keys are sorted and separators are (",", ":")
    const payload = { z: 1, a: 2, m: 3 };
    const result = canonicalJson(payload);
    const decoded = new TextDecoder().decode(result);
    expect(decoded).toBe('{"a":2,"m":3,"z":1}');
  });
});

describe("D5.6 field set", () => {
  it("golden payload has exactly the D5.6 field set", () => {
    const golden = loadGolden();
    const fields = new Set(Object.keys(golden.payload));
    const expected = new Set([
      "request_id", "command", "fingerprint", "reviewer_id", "decision",
      "approved_at", "org_id", "project_id", "device_id", "registry_version",
      "policy_sequence", "user_id", "key_id", "nonce", "not_after",
    ]);
    expect(fields).toEqual(expected);
  });
});

describe("canonicalBytes (non-ASCII cross-language case)", () => {
  it("produces the same canonical bytes as Python for non-ASCII payload", () => {
    // The non-ASCII case tests two cross-language differences:
    // 1. Unicode escaping: Python json.dumps(ensure_ascii=True) escapes
    //    non-ASCII as \uXXXX; JS JSON.stringify does NOT escape by default.
    // 2. Float formatting: Python serialises 1700001000.0 as "1700001000.0";
    //    JS serialises it as "1700001000" (no trailing .0).
    // The TS canonicalJson must match Python's behaviour for both.
    const golden = loadGolden();
    const nonAsciiCase = golden.cases?.[0];
    if (!nonAsciiCase) {
      throw new Error("non_ascii case not found in golden fixture (run Python guards first)");
    }
    expect(nonAsciiCase.name).toBe("non_ascii");
    const result = canonicalBytes(nonAsciiCase.tag, nonAsciiCase.payload);
    const resultHex = Buffer.from(result).toString("hex");
    expect(resultHex).toBe(nonAsciiCase.canonical_bytes_hex);
  });
});
